code_example:
#include <memory>
#include <iostream>

class Widget {
public:
    Widget() { std::cout << "Widget constructed" << std::endl; }
    ~Widget() { std::cout << "Widget destroyed" << std::endl; }
    void do_something() { std::cout << "Doing something" << std::endl; }
};

int main() {
    // Create a unique_ptr to manage a Widget instance
    auto widgetPtr = std::make_unique<Widget>();
    widgetPtr->do_something();
    // Transfer ownership to another unique_ptr
    auto anotherPtr = std::move(widgetPtr);
    if (!widgetPtr) {
        std::cout << "widgetPtr is now null after move" << std::endl;
    }
    // unique_ptr automatically deletes the Widget when it goes out of scope
    return 0;
}
